SELECT OrderDate, Total,
       SUM(Total) OVER (
           ORDER BY OrderDate
           [BLANK1] BETWEEN [BLANK2] AND CURRENT ROW
       ) AS RunningTotal
FROM Sales.Orders;

WITH Ranked AS (
    SELECT Category, ProductId, Revenue,
           [BLANK1]() OVER (
               [BLANK2] Category
               ORDER BY Revenue DESC
           ) AS rn
    FROM Sales.ProductRevenue
)
SELECT * FROM Ranked WHERE rn <= 3;
